        D.el("circle", {cx: pos[0], cy: pos[1], r: NUM_R, fill: "var(--bg)", stroke: "var(--term)", "stroke-width": 2}, sk.num);
        D.el("text", {x: pos[0], y: pos[1] + 8.5, "font-size": 24, "text-anchor": "middle", fill: "var(--term)", "font-weight": "bold", style: "font-variant-numeric:tabular-nums"}, sk.num).textContent = String(sk.i + 1);
